how.python:
import math


def gcd_iter(a, b):
    """迭代版欧几里得算法"""
    while b != 0:
        a, b = b, a % b
    return a


def gcd_rec(a, b):
    """递归版"""
    return a if b == 0 else gcd_rec(b, a % b)


def lcm(a, b):
    return a // gcd_iter(a, b) * b


def gcd_multi(nums):
    """多数的最大公约数：两两归纳"""
    g = 0
    for x in nums:
        g = gcd_iter(g, x)
    return g


def gcd_stein(a, b):
    """Stein 算法（二进制 GCD），用移位/减法避免取模"""
    if a == 0:
        return b
    if b == 0:
        return a
    shift = 0
    while ((a | b) & 1) == 0:
        a >>= 1
        b >>= 1
        shift += 1
    while (a & 1) == 0:
        a >>= 1
    while b:
        while (b & 1) == 0:
            b >>= 1
        if a > b:
            a, b = b, a
        b -= a
    return a << shift


if __name__ == "__main__":
    assert gcd_iter(12, 18) == 6
    assert gcd_iter(1071, 462) == 21
    assert gcd_iter(0, 5) == 5
    assert gcd_iter(7, 7) == 7
    assert gcd_rec(252, 105) == 21
    assert gcd_multi([12, 18, 30]) == 6
    assert lcm(4, 6) == 12
    assert lcm(21, 6) == 42

    # 交叉验证 Stein 与辗转相除
    import random
    random.seed(42)
    for _ in range(2000):
        a = random.randint(0, 10**9)
        b = random.randint(0, 10**9)
        assert gcd_stein(a, b) == math.gcd(a, b), (a, b)
        assert gcd_iter(a, b) == math.gcd(a, b), (a, b)
        assert lcm(a, b) == math.lcm(a, b) or math.gcd(a, b) == 0, (a, b)

    print("All tests passed.")
